glsl3.frag:
precision highp float;
layout(std140) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_probeInfo;
  mediump vec4 cc_debug_view_mode;
};
layout(std140) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
vec4 CCSampleWithAlphaSeparated(sampler2D tex, vec2 uv) {
#if CC_USE_EMBEDDED_ALPHA
  return vec4(texture(tex, uv).rgb, texture(tex, uv + vec2(0.0, 0.5)).r);
#else
  return texture(tex, uv);
#endif
}
#if USE_ALPHA_TEST
  layout(std140) uniform ALPHA_TEST_DATA {
    float alphaThreshold;
  };
#endif
void ALPHA_TEST (in vec4 color) {
  #if USE_ALPHA_TEST
    if (color.a < alphaThreshold) discard;
  #endif
}
void ALPHA_TEST (in float alpha) {
  #if USE_ALPHA_TEST
    if (alpha < alphaThreshold) discard;
  #endif
}
in vec4 color;
in vec2 uv0;
uniform sampler2D cc_spriteTexture;
#if USE_WAVE
  uniform sampler2D waveTexture;
#endif
#if USE_CAUSTIC
  uniform sampler2D causticTexture;
#endif
layout(std140) uniform WaterConstants {
  vec4 uvParams;
  vec4 waveParams;
  vec4 waveTextureParams;
  vec4 causticParams;
  vec4 causticMotion;
  vec4 fadeParams;
  vec4 waterTint;
};
const float PI = 3.141592653589793;
vec2 panner (vec2 uv, float direction01, float speed, vec2 offset, float tiling) {
  float direction = direction01 * 2.0 - 1.0;
  vec2 dir = vec2(cos(PI * direction), sin(PI * direction));
  return dir * cc_time.x * speed + offset + uv * tiling;
}
vec3 rgbSplit (float splitAmount, sampler2D tex, vec2 uv) {
  vec2 uvR = uv + vec2( splitAmount,  splitAmount);
  vec2 uvG = uv + vec2( splitAmount, -splitAmount);
  vec2 uvB = uv + vec2(-splitAmount, -splitAmount);
  float r = texture(tex, uvR).r;
  float g = texture(tex, uvG).g;
  float b = texture(tex, uvB).b;
  return vec3(r, g, b);
}
#if USE_CAUSTIC
  vec3 calculateCaustic (vec2 baseUv) {
    float scale = max(causticParams.y, 0.001);
    float splitAmount = causticParams.w * 0.01;
    vec2 uv1 = panner(
      baseUv,
      causticMotion.x,
      causticParams.z,
      vec2(0.0, 0.0),
      1.0 / scale
    );
    vec2 uv2 = panner(
      baseUv,
      causticMotion.y,
      causticParams.z * 0.93,
      vec2(0.37, 0.17),
      -1.0 / scale
    );
    vec3 layer1 = rgbSplit(splitAmount, causticTexture, uv1);
    vec3 layer2 = rgbSplit(splitAmount, causticTexture, uv2);
    return min(layer1, layer2) * causticParams.x * causticMotion.z;
  }
#endif
vec4 frag () {
  vec2 uv = uv0;
  #if USE_TILING
    uv = uv * uvParams.xy + waveTextureParams.zw;
    float farDepth = pow(clamp(uv0.y, 0.0, 1.0), max(fadeParams.w, 1.0));
    uv.y += farDepth * fadeParams.z;
  #endif
  #if USE_WAVE
    vec2 waveUv = uv0 * waveTextureParams.xy
      + cc_time.x * waveParams.x * waveParams.zw;
    vec2 waveOffset = (texture(waveTexture, waveUv).xy * 2.0 - 1.0)
      * waveParams.y;
    uv += waveOffset;
  #endif
  vec4 o = CCSampleWithAlphaSeparated(cc_spriteTexture, uv);
  #if USE_CAUSTIC
    o.rgb += calculateCaustic(uv0) * o.a;
  #endif
  #if USE_COLOR_STEP
    float depthFade = 1.0 - smoothstep(-0.1, 1.5, uv0.y * uvParams.z);
    o.rgb *= mix(1.0, depthFade, fadeParams.x);
  #endif
  #if USE_ALPHA_STEP
    float shoreAlpha = smoothstep(-0.2, 0.75, uv0.y * uvParams.w);
    o.a *= shoreAlpha;
  #endif
  o.rgb *= waterTint.rgb;
  o.a *= waterTint.a * fadeParams.y;
  o *= color;
  ALPHA_TEST(o);
  return o;
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

